#pragma once

// Single-file mobile controller. All resources are served locally by the Windows app.
static constexpr const char* kRemotePage = R"DSP_HTML(<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>Dual Channel DSP · Remote</title><style>
:root{color-scheme:dark;--bg:#111821;--panel:#1d2734;--card:#253140;--muted:#a0b3c7;--accent:#65cad8;--border:#34485d}
*{box-sizing:border-box}body{font:15px system-ui,-apple-system,'Segoe UI',sans-serif;background:var(--bg);color:#edf5fb;margin:0;padding:16px max(12px,env(safe-area-inset-right)) 45px}header{max-width:1160px;margin:auto;display:flex;gap:12px;justify-content:space-between;align-items:center;flex-wrap:wrap}h1{font-size:21px;margin:0}h2{font-size:19px;margin:0 0 14px;color:white}.muted,small{color:var(--muted)}.status{font-size:12px;color:var(--accent)}.bar{max-width:1160px;margin:14px auto;display:flex;flex-wrap:wrap;gap:8px;align-items:center}.bar input{width:145px}.channels{max-width:1160px;margin:auto;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.panel{background:var(--panel);border:1px solid var(--border);border-radius:15px;padding:16px;min-width:0}.control{display:grid;grid-template-columns:98px 1fr 65px;gap:7px;align-items:center;margin:9px 0}.control label{font-size:13px;color:var(--muted)}.control output{text-align:right;font-variant-numeric:tabular-nums;font-size:12px;color:#e1eef4}input[type=range]{width:100%;accent-color:var(--accent);min-width:0}input[type=text],select{background:#111c28;color:white;border:1px solid #476073;border-radius:8px;padding:9px;min-width:0;width:100%}button{background:var(--card);color:white;border:1px solid #547081;border-radius:8px;padding:10px;cursor:pointer}button.primary{background:#287d91;border-color:#5bbbcf}button:active{filter:brightness(1.3)}.routing{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:12px}.routing label{font-size:12px;color:var(--muted)}.checkline{display:flex;align-items:center;gap:7px;font-size:13px;margin:12px 0}.checkline input{accent-color:var(--accent)}.filter{background:var(--card);border-radius:9px;padding:10px;margin:11px 0}.filter .head{display:flex;justify-content:space-between;gap:8px;align-items:center}.filter select{width:104px;padding:6px}.band{background:var(--card);border-radius:8px;padding:9px;margin:9px 0}.band strong{font-size:12px;color:var(--accent)}.graph{width:100%;height:195px;display:block;background:#101923;border-radius:8px;touch-action:none;margin-bottom:13px}.tabs{display:none}.group{display:grid;grid-template-columns:1fr 1fr;gap:10px}.toast{position:fixed;bottom:10px;left:12px;right:12px;max-width:480px;margin:auto;background:#153644;padding:12px;border-radius:9px;text-align:center;display:none}#pin{display:none;max-width:400px;margin:10vh auto;padding:25px;background:var(--panel);border-radius:14px}#pin input{margin:12px 0;font-size:20px;letter-spacing:4px;text-align:center}.note{max-width:1160px;margin:15px auto;font-size:12px;color:var(--muted)}
@media(max-width:790px){.channels{display:block}.panel{margin-bottom:14px}.tabs{display:flex;max-width:1160px;margin:0 auto 10px;gap:8px}.tabs button{flex:1}.panel.hidden{display:none}.bar{gap:7px}.bar input{flex:1}.routing{gap:7px}h1{font-size:19px}}
</style></head><body>
<header><div><h1>Dual Channel DSP</h1><small>Wi-Fi remote · processing runs on your Windows PC</small></div><span id="status" class="status">Connecting…</span></header>
<div id="pin"><h2>Enter remote PIN</h2><p class="muted">Find the 6-digit PIN in the Windows application.</p><input type="text" id="pinvalue" inputmode="numeric" maxlength="6" placeholder="000000"><button class="primary" onclick="connectPin()">Connect</button></div>
<div id="app" style="display:none"><div class="bar"><input id="presetname" type="text" placeholder="Preset name" maxlength="60"><button onclick="savePreset()">Save preset</button><select id="presets" aria-label="Saved presets"><option>Saved presets</option></select><button onclick="loadPreset()">Load preset</button></div>
<div class="tabs"><button onclick="showTab(0)">Channel 1</button><button onclick="showTab(1)">Channel 2</button></div><main class="channels" id="channels"></main><p class="note">Changes are applied to the PC in real time. Separate output routes are required. The graph shows frequency response, excluding output level and delay. This local HTTP remote is not encrypted; use only on a trusted private Wi-Fi network.</p></div><div class="toast" id="toast"></div>
<script>
let pin=localStorage.getItem('dspPin')||'',model=null,selectedTab=0,busy=false,editingUntil=0;
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
function notice(s){$('toast').textContent=s;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',2800)}
async function api(path,method='GET',data){const r=await fetch(path,{method,headers:{'X-DSP-PIN':pin,'Content-Type':'application/json'},body:data?JSON.stringify(data):undefined,cache:'no-store'});if(r.status===401){$('app').style.display='none';$('pin').style.display='block';throw Error('Enter PIN from the Windows application')}if(!r.ok)throw Error((await r.text()).slice(0,120));return r.json()}
function connectPin(){pin=$('pinvalue').value.trim();localStorage.setItem('dspPin',pin);refresh(true)}
function showTab(i){selectedTab=i;document.querySelectorAll('.panel').forEach((p,j)=>p.classList.toggle('hidden',i!==j));}
const format=(v,d=1)=>Number(v).toFixed(d);function range(ch,key,label,val,min,max,step,unit,band){const idx=band===undefined?'':` data-band="${band}"`,log=key==='frequencyHz'||key.endsWith('.frequency');return `<div class="control"><label>${label}</label><input type="range" data-ch="${ch}" data-key="${key}"${idx} data-log="${log?'1':'0'}" min="${log?0:min}" max="${log?1000:max}" step="${log?1:step}" value="${log?Math.round(Math.log(Math.max(20,val)/20)/Math.log(1000)*1000):val}"><output>${format(val,step<.1?2:step<1?1:0)} ${unit}</output></div>`}
function cutoff(ch,key,caption,filter){return `<div class="filter"><div class="head"><label class="checkline"><input type="checkbox" data-ch="${ch}" data-key="${key}.enabled" ${filter.enabled?'checked':''}>${caption}</label><select data-ch="${ch}" data-key="${key}.slope"><option value="12" ${filter.slope==12?'selected':''}>12 dB/oct</option><option value="24" ${filter.slope==24?'selected':''}>24 dB/oct</option></select></div>${range(ch,key+'.frequency','Frequency',filter.frequency,20,20000,1,'Hz')}</div>`}
function channel(c,i,m){return `<section class="panel" data-channel="${i}"><h2>Channel ${i+1}</h2><div class="control" style="grid-template-columns:98px 1fr"><label>Name</label><input type="text" maxlength="40" data-ch="${i}" data-key="name" value="${esc(c.name)}"></div><div class="routing"><div><label>Input</label><select data-ch="${i}" data-key="inputRoute">${options(m.inputs,c.inputRoute)}</select></div><div><label>Output</label><select data-ch="${i}" data-key="outputRoute">${options(m.outputs,c.outputRoute)}</select></div></div><canvas class="graph" data-graph="${i}" width="640" height="350"></canvas>${range(i,'levelDb','Level',c.levelDb,-90,18,.1,'dB')}${range(i,'delayMs','Delay',c.delayMs,0,2000,.01,'ms')}<label class="checkline"><input type="checkbox" data-ch="${i}" data-key="invertPolarity" ${c.invertPolarity?'checked':''}>Invert polarity (Ø)</label><h2 style="font-size:15px;color:var(--accent)">Filters</h2>${cutoff(i,'highPass','High-pass',c.highPass)}${cutoff(i,'lowPass','Low-pass',c.lowPass)}<h2 style="font-size:15px;color:var(--accent)">Parametric EQ · six bands</h2>${c.eq.map((b,j)=>`<div class="band"><strong>Band ${j+1}</strong>${range(i,'frequencyHz','Frequency',b.frequencyHz,20,20000,1,'Hz',j)}${range(i,'gainDb','Gain',b.gainDb,-18,18,.1,'dB',j)}${range(i,'q','Q',b.q,.1,15,.05,'',j)}</div>`).join('')}</section>`}
function options(arr,selected){return `<option value="-1">Unassigned</option>`+arr.map((s,j)=>`<option value="${j}" ${j===selected?'selected':''}>${j+1}: ${esc(s)}</option>`).join('')}
async function send(ch,key,value,band){try{await api('/api/set','POST',{channel:ch,key,value,...(band===undefined?{}:{band})})}catch(e){notice(e.message)}}
function handlers(){document.querySelectorAll('[data-key]').forEach(el=>{const fire=()=>{const ch=Number(el.dataset.ch),key=el.dataset.key,band=el.dataset.band===undefined?undefined:Number(el.dataset.band);let val=el.type==='checkbox'?el.checked:el.type==='range'||(el.tagName==='SELECT'&&key!=='name')?Number(el.value):el.value;if(el.type==='range'&&el.dataset.log==='1')val=Math.round(20*Math.pow(1000,val/1000));editingUntil=Date.now()+1100;if(el.type==='range'){el.nextElementSibling.textContent=String(Number(val).toFixed(Number(el.step)<.1?2:Number(el.step)<1?1:0))+' '+((el.nextElementSibling.textContent.match(/[a-zA-Z/]+$/)||[''])[0]);}if(el.type==='text'){clearTimeout(el._timer);el._timer=setTimeout(()=>send(ch,key,val,band),350)}else send(ch,key,val,band)};el.addEventListener(el.type==='range'?'input':'change',fire)})}
function render(m){model=m;$('pin').style.display='none';$('app').style.display='block';$('channels').innerHTML=m.channels.map((c,i)=>channel(c,i,m)).join('');handlers();if(window.innerWidth<=790)showTab(selectedTab);m.channels.forEach((c,i)=>graph(document.querySelector(`[data-graph="${i}"]`),c));}
function graph(canvas,c){if(!canvas)return;const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,pad=36,right=13,top=14,bottom=24;ctx.clearRect(0,0,w,h);ctx.font='20px system-ui';ctx.lineWidth=1;const x=f=>pad+(Math.log10(f/20)/3)*(w-pad-right),y=db=>top+(24-db)/48*(h-top-bottom);ctx.strokeStyle='#284052';ctx.fillStyle='#839ab1';[20,50,100,200,500,1000,2000,5000,10000,20000].forEach(f=>{let a=x(f);ctx.beginPath();ctx.moveTo(a,top);ctx.lineTo(a,h-bottom);ctx.stroke();if([20,100,1000,10000].includes(f))ctx.fillText(f>=1000?(f/1000)+'k':f,a-10,h-5)});[-24,-12,0,12,24].forEach(db=>{let a=y(db);ctx.strokeStyle=db===0?'#62889a':'#284052';ctx.beginPath();ctx.moveTo(pad,a);ctx.lineTo(w-right,a);ctx.stroke();ctx.fillText(String(db),2,a+6)});ctx.strokeStyle='#65cad8';ctx.lineWidth=4;ctx.beginPath();c.curve.forEach((db,j)=>{let a=x(20*Math.pow(1000,j/(c.curve.length-1)));j?ctx.lineTo(a,y(Math.max(-24,Math.min(24,db)))):ctx.moveTo(a,y(Math.max(-24,Math.min(24,db))))});ctx.stroke();c.eq.forEach((b,j)=>{ctx.beginPath();ctx.arc(x(b.frequencyHz),y(b.gainDb),6,0,7);ctx.fillStyle='#f6cc65';ctx.fill();});}
async function refresh(force){if(busy||!force&&Date.now()<editingUntil)return;busy=true;try{const state=await api('/api/state');$('status').textContent='Connected · '+state.device;render(state);}catch(e){$('status').textContent=e.message;if(e.message.includes('PIN'))$('pin').style.display='block'}finally{busy=false}}
async function presets(){try{const m=await api('/api/presets');$('presets').innerHTML=`<option value="">Select preset</option>`+m.names.map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join('')}catch(e){}}
async function savePreset(){const name=$('presetname').value.trim();if(!name){notice('Enter a preset name');return}try{await api('/api/save','POST',{name});notice('Saved on Windows PC');presets()}catch(e){notice(e.message)}}
async function loadPreset(){const name=$('presets').value;if(!name)return;try{await api('/api/load','POST',{name});notice('Preset loaded');setTimeout(()=>refresh(true),200)}catch(e){notice(e.message)}}
$('pinvalue').addEventListener('keydown',e=>{if(e.key==='Enter')connectPin()});refresh(true);setInterval(()=>refresh(false),850);setInterval(presets,8000);setTimeout(presets,500);
</script></body></html>)DSP_HTML";
